#!/usr/bin/env python3
"""Grade the check-gate `sheet` task: run the pristine visible tests plus
hidden tests derived from the task's specification against a copy of the
workspace whose own tests/ directory is replaced. Editing the workspace's tests
changes nothing here. The last output line is `<failed> failed, <passed> passed`."""
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

TEST_FILES = {'tests/__init__.py': '# Unit tests.\n', 'tests/run.py': '"""Run the unit tests under tests/ and report them like pytest\'s summary:\nthe failure details first, then one `FAILED <test> - <reason>` line per\nfailing test and a count line. Exit status 1 when anything failed."""\nimport os\nimport sys\nimport unittest\n\n\ndef main():\n    here = os.path.dirname(os.path.abspath(__file__))\n    root = os.path.dirname(here)\n    sys.path.insert(0, root)\n    suite = unittest.defaultTestLoader.discover(here, pattern="test_*.py", top_level_dir=root)\n    result = unittest.TestResult()\n    suite.run(result)\n    failed = result.failures + result.errors\n    for test, trace in failed:\n        print("_" * 12 + " " + test.id() + " " + "_" * 12)\n        print(trace.rstrip())\n        print()\n    failing_methods = set()\n    for test, trace in failed:\n        case = getattr(test, "test_case", test)\n        failing_methods.add(case.id())\n        parts = case.id().rsplit(".", 2)\n        if len(parts) == 3:\n            module, cls, method = parts\n            name = "%s.py::%s::%s" % (module.replace(".", "/"), cls, method)\n        else:\n            name = case.id()\n        if case is not test:\n            name += " " + test._subDescription()\n        lines = trace.strip().splitlines()\n        reason = lines[-1] if lines else ""\n        print("FAILED %s - %s" % (name, reason))\n    print("%d failed, %d passed" % (len(failing_methods), result.testsRun - len(failing_methods)))\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_cells.py': 'import unittest\n\nfrom sheet import Sheet\n\nclass SheetCellsTest(unittest.TestCase):\n    def assertValue(self, got, expected):\n        self.assertEqual(got, expected)\n        self.assertIs(type(got), type(expected))\n\n    def test_raw_int(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'42\')\n        self.assertValue(sheet.get(\'A1\'), 42)\n\n    def test_raw_negative_int(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'-7\')\n        self.assertValue(sheet.get(\'A1\'), -7)\n\n    def test_raw_float(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'2.5\')\n        self.assertValue(sheet.get(\'A1\'), 2.5)\n\n    def test_raw_text(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'hello\')\n        self.assertValue(sheet.get(\'A1\'), \'hello\')\n\n    def test_empty_cell_is_none(self):\n        sheet = Sheet()\n        self.assertValue(sheet.get(\'C3\'), None)\n\n    def test_references_are_case_insensitive(self):\n        sheet = Sheet()\n        sheet.set(\'b2\', \'5\')\n        self.assertValue(sheet.get(\'B2\'), 5)\n\n    def test_setting_empty_clears(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'5\')\n        sheet.set(\'A1\', \'\')\n        self.assertValue(sheet.get(\'A1\'), None)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_formulas.py': 'import unittest\n\nfrom sheet import Sheet\n\nclass SheetFormulasTest(unittest.TestCase):\n    def assertValue(self, got, expected):\n        self.assertEqual(got, expected)\n        self.assertIs(type(got), type(expected))\n\n    def test_precedence(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1+2*3\')\n        self.assertValue(sheet.get(\'A1\'), 7)\n\n    def test_parentheses(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=(1+2)*3\')\n        self.assertValue(sheet.get(\'A1\'), 9)\n\n    def test_power_is_right_associative(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=2^3^2\')\n        self.assertValue(sheet.get(\'A1\'), 512)\n\n    def test_unary_minus_binds_tighter_than_power(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=-2^2\')\n        self.assertValue(sheet.get(\'A1\'), 4)\n\n    def test_division_float(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=7/2\')\n        self.assertValue(sheet.get(\'A1\'), 3.5)\n\n    def test_division_whole_is_int(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=6/2\')\n        self.assertValue(sheet.get(\'A1\'), 3)\n\n    def test_reference(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'3\')\n        sheet.set(\'A2\', \'=A1*2\')\n        self.assertValue(sheet.get(\'A2\'), 6)\n\n    def test_recalculation(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'3\')\n        sheet.set(\'A2\', \'=A1*2\')\n        sheet.set(\'A1\', \'10\')\n        self.assertValue(sheet.get(\'A2\'), 20)\n\n    def test_empty_reference_is_zero(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B9+1\')\n        self.assertValue(sheet.get(\'A1\'), 1)\n\n    def test_plain_empty_reference(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B9\')\n        self.assertValue(sheet.get(\'A1\'), 0)\n\n    def test_concatenation(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'="a"&1&TRUE\')\n        self.assertValue(sheet.get(\'A1\'), \'a1TRUE\')\n\n    def test_concatenation_with_empty(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B9&"x"\')\n        self.assertValue(sheet.get(\'A1\'), \'x\')\n\n    def test_string_escape(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'="say ""hi"""\')\n        self.assertValue(sheet.get(\'A1\'), \'say "hi"\')\n\n    def test_comparison_numbers(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=2>1\')\n        self.assertValue(sheet.get(\'A1\'), True)\n\n    def test_comparison_text_case_insensitive(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'="abc"="ABC"\')\n        self.assertValue(sheet.get(\'A1\'), True)\n\n    def test_number_less_than_text(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1<"a"\')\n        self.assertValue(sheet.get(\'A1\'), True)\n\n    def test_booleans_in_arithmetic(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=TRUE+1\')\n        self.assertValue(sheet.get(\'A1\'), 2)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_functions.py': 'import unittest\n\nfrom sheet import Sheet\n\nclass SheetFunctionsTest(unittest.TestCase):\n    def assertValue(self, got, expected):\n        self.assertEqual(got, expected)\n        self.assertIs(type(got), type(expected))\n\n    def test_sum_range_skips_text(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'1\')\n        sheet.set(\'A2\', \'2\')\n        sheet.set(\'A3\', \'x\')\n        sheet.set(\'B1\', \'=SUM(A1:A3)\')\n        self.assertValue(sheet.get(\'B1\'), 3)\n\n    def test_sum_arguments(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=SUM(1, 2.5, 3)\')\n        self.assertValue(sheet.get(\'A1\'), 6.5)\n\n    def test_average(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'1\')\n        sheet.set(\'A2\', \'2\')\n        sheet.set(\'B1\', \'=AVERAGE(A1:A2)\')\n        self.assertValue(sheet.get(\'B1\'), 1.5)\n\n    def test_average_of_nothing(self):\n        sheet = Sheet()\n        sheet.set(\'B1\', \'=AVERAGE(A1:A3)\')\n        self.assertValue(sheet.get(\'B1\'), \'#DIV/0!\')\n\n    def test_min_max_count(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'4\')\n        sheet.set(\'A2\', \'-1\')\n        sheet.set(\'A3\', \'9\')\n        sheet.set(\'B1\', \'=MIN(A1:A3)\')\n        sheet.set(\'B2\', \'=MAX(A1:A3)\')\n        sheet.set(\'B3\', \'=COUNT(A1:A3)\')\n        self.assertValue(sheet.get(\'B1\'), -1)\n        self.assertValue(sheet.get(\'B2\'), 9)\n        self.assertValue(sheet.get(\'B3\'), 3)\n\n    def test_if(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'5\')\n        sheet.set(\'B1\', \'=IF(A1>2, "big", "small")\')\n        self.assertValue(sheet.get(\'B1\'), \'big\')\n\n    def test_abs(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=ABS(-3.5)\')\n        self.assertValue(sheet.get(\'A1\'), 3.5)\n\n    def test_round_half_away_from_zero(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=ROUND(2.5, 0)\')\n        sheet.set(\'A2\', \'=ROUND(-2.5, 0)\')\n        self.assertValue(sheet.get(\'A1\'), 3)\n        self.assertValue(sheet.get(\'A2\'), -3)\n\n    def test_function_names_case_insensitive(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=sum(1, 2)\')\n        self.assertValue(sheet.get(\'A1\'), 3)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_errors.py': 'import unittest\n\nfrom sheet import Sheet\n\nclass SheetErrorsTest(unittest.TestCase):\n    def assertValue(self, got, expected):\n        self.assertEqual(got, expected)\n        self.assertIs(type(got), type(expected))\n\n    def test_division_by_zero(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1/0\')\n        self.assertValue(sheet.get(\'A1\'), \'#DIV/0!\')\n\n    def test_text_in_arithmetic(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'="a"+1\')\n        self.assertValue(sheet.get(\'A1\'), \'#VALUE!\')\n\n    def test_unknown_function(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=FOO(1)\')\n        self.assertValue(sheet.get(\'A1\'), \'#NAME?\')\n\n    def test_bad_reference(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=AA1\')\n        sheet.set(\'A2\', \'=A100\')\n        self.assertValue(sheet.get(\'A1\'), \'#REF!\')\n        self.assertValue(sheet.get(\'A2\'), \'#REF!\')\n\n    def test_syntax_error(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1+\')\n        self.assertValue(sheet.get(\'A1\'), \'#ERROR!\')\n\n    def test_no_real_power(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=(-8)^0.5\')\n        self.assertValue(sheet.get(\'A1\'), \'#NUM!\')\n\n    def test_error_propagates(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1/0\')\n        sheet.set(\'A2\', \'=A1+1\')\n        self.assertValue(sheet.get(\'A2\'), \'#DIV/0!\')\n\n    def test_left_error_wins(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1/0\')\n        sheet.set(\'A2\', \'=A1+"x"\')\n        sheet.set(\'A3\', \'="x"+A1\')\n        self.assertValue(sheet.get(\'A2\'), \'#DIV/0!\')\n        self.assertValue(sheet.get(\'A3\'), \'#DIV/0!\')\n\n    def test_cycle(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B1\')\n        sheet.set(\'B1\', \'=A1\')\n        self.assertValue(sheet.get(\'A1\'), \'#CYCLE!\')\n        self.assertValue(sheet.get(\'B1\'), \'#CYCLE!\')\n\n    def test_depends_on_cycle(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B1\')\n        sheet.set(\'B1\', \'=A1\')\n        sheet.set(\'C1\', \'=A1+1\')\n        self.assertValue(sheet.get(\'C1\'), \'#CYCLE!\')\n\n    def test_self_reference(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=A1+1\')\n        self.assertValue(sheet.get(\'A1\'), \'#CYCLE!\')\n\n    def test_range_outside_function(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'1\')\n        sheet.set(\'A2\', \'=A1:A1\')\n        self.assertValue(sheet.get(\'A2\'), \'#ERROR!\')\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_references.py': 'import unittest\n\nfrom sheet import Sheet\n\nclass SheetReferencesTest(unittest.TestCase):\n    def test_invalid_reference_get(self):\n        with self.assertRaises(ValueError):\n            Sheet().get(\'AA1\')\n\n    def test_invalid_reference_row_zero(self):\n        with self.assertRaises(ValueError):\n            Sheet().set(\'A0\', \'1\')\n\n    def test_invalid_reference_row_100(self):\n        with self.assertRaises(ValueError):\n            Sheet().get(\'A100\')\n\n    def test_invalid_reference_digits_first(self):\n        with self.assertRaises(ValueError):\n            Sheet().get(\'1A\')\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_hidden_sheet.py': 'import unittest\n\nfrom sheet import Sheet\n\nclass SheetHiddenTest(unittest.TestCase):\n    def assertValue(self, got, expected):\n        self.assertEqual(got, expected)\n        self.assertIs(type(got), type(expected))\n\n    def test_round_uses_decimal_text(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=ROUND(1.005, 2)\')\n        sheet.set(\'A2\', \'=ROUND(2.675, 2)\')\n        self.assertValue(sheet.get(\'A1\'), 1.01)\n        self.assertValue(sheet.get(\'A2\'), 2.68)\n\n    def test_if_is_lazy_about_cycles(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=IF(TRUE, 1, A1)\')\n        self.assertValue(sheet.get(\'A1\'), 1)\n\n    def test_if_is_lazy_about_errors(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=IF(FALSE, 1/0, 2)\')\n        self.assertValue(sheet.get(\'A1\'), 2)\n\n    def test_if_text_condition(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=IF("yes", 1, 2)\')\n        self.assertValue(sheet.get(\'A1\'), \'#VALUE!\')\n\n    def test_negated_empty(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=-B9\')\n        self.assertValue(sheet.get(\'A1\'), 0)\n\n    def test_negative_exponent(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=2^-1\')\n        self.assertValue(sheet.get(\'A1\'), 0.5)\n\n    def test_number_text_comparison(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=5<"3"\')\n        sheet.set(\'A2\', \'="b">"A"\')\n        self.assertValue(sheet.get(\'A1\'), True)\n        self.assertValue(sheet.get(\'A2\'), True)\n\n    def test_empty_compares_as_blank_or_zero(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B9=""\')\n        sheet.set(\'A2\', \'=B9=0\')\n        self.assertValue(sheet.get(\'A1\'), True)\n        self.assertValue(sheet.get(\'A2\'), True)\n\n    def test_sum_text_argument(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=SUM("a")\')\n        self.assertValue(sheet.get(\'A1\'), \'#VALUE!\')\n\n    def test_sum_range_skips_booleans(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=TRUE\')\n        sheet.set(\'A2\', \'4\')\n        sheet.set(\'B1\', \'=SUM(A1:A2)\')\n        self.assertValue(sheet.get(\'B1\'), 4)\n\n    def test_reversed_range(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'1\')\n        sheet.set(\'B3\', \'2\')\n        sheet.set(\'C1\', \'=SUM(B3:A1)\')\n        self.assertValue(sheet.get(\'C1\'), 3)\n\n    def test_range_with_bad_reference(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=SUM(B1:B100)\')\n        self.assertValue(sheet.get(\'A1\'), \'#REF!\')\n\n    def test_error_inside_range(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1/0\')\n        sheet.set(\'B1\', \'=SUM(A1:A2)\')\n        self.assertValue(sheet.get(\'B1\'), \'#DIV/0!\')\n\n    def test_whole_float_product_is_int(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=2.5*2\')\n        self.assertValue(sheet.get(\'A1\'), 5)\n\n    def test_concatenate_numbers(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=2.5&""\')\n        sheet.set(\'A2\', \'=6/2&""\')\n        self.assertValue(sheet.get(\'A1\'), \'2.5\')\n        self.assertValue(sheet.get(\'A2\'), \'3\')\n\n    def test_dependency_chain(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'1\')\n        sheet.set(\'A2\', \'=A1+1\')\n        sheet.set(\'A3\', \'=A2+1\')\n        sheet.set(\'A1\', \'10\')\n        self.assertValue(sheet.get(\'A3\'), 12)\n\n    def test_three_cycle(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=B1\')\n        sheet.set(\'B1\', \'=C1\')\n        sheet.set(\'C1\', \'=A1*2\')\n        sheet.set(\'D1\', \'=SUM(A1, 1)\')\n        self.assertValue(sheet.get(\'A1\'), \'#CYCLE!\')\n        self.assertValue(sheet.get(\'C1\'), \'#CYCLE!\')\n        self.assertValue(sheet.get(\'D1\'), \'#CYCLE!\')\n\n    def test_wrong_arity(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=ROUND(1)\')\n        sheet.set(\'A2\', \'=IF(1, 2)\')\n        self.assertValue(sheet.get(\'A1\'), \'#VALUE!\')\n        self.assertValue(sheet.get(\'A2\'), \'#VALUE!\')\n\n    def test_min_of_nothing(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=MIN(B1:B3)\')\n        self.assertValue(sheet.get(\'A1\'), 0)\n\n    def test_bare_word(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=hello\')\n        self.assertValue(sheet.get(\'A1\'), \'#NAME?\')\n\n    def test_reference_to_text(self):\n        sheet = Sheet()\n        sheet.set(\'B1\', \'hi\')\n        sheet.set(\'A1\', \'=B1\')\n        self.assertValue(sheet.get(\'A1\'), \'hi\')\n\n    def test_trailing_tokens(self):\n        sheet = Sheet()\n        sheet.set(\'A1\', \'=1 2\')\n        self.assertValue(sheet.get(\'A1\'), \'#ERROR!\')\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

SKIP = {"tests", ".git", ".home", "__pycache__", "events.jsonl"}


def main():
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp) / "workspace"
        root.mkdir()
        for entry in workspace.iterdir():
            if entry.name in SKIP or entry.name.startswith(".") or entry.is_symlink():
                continue
            if entry.is_dir():
                shutil.copytree(entry, root / entry.name, symlinks=False,
                                ignore=shutil.ignore_patterns("__pycache__"))
            elif entry.is_file():
                shutil.copy2(entry, root / entry.name)
        for rel, text in TEST_FILES.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8")
        try:
            result = subprocess.run([sys.executable, "tests/run.py"], cwd=root, capture_output=True,
                                    text=True, timeout=90)
        except subprocess.TimeoutExpired:
            print("tests timed out")
            return 1
        output = result.stdout + result.stderr
        print(output[-4000:])
        return 0 if result.returncode == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
